#!/usr/bin/env node
/**
 * THE PARITY HARNESS SHOWN FAILING ON EVERY BRANCH IT HAS.
 *
 * Instruments carry the shape of their subject; this estate has five instances. A harness that has
 * only ever passed is not yet a check. Each case below perturbs exactly one thing, records what the
 * harness printed VERBATIM, and puts the oracle back. The transcript is generated by this script
 * rather than pasted, so it cannot go stale against the harness it describes.
 *
 * Writes HARNESS-SHOWN-FAILING.md beside itself.
 */
import { readFileSync, writeFileSync, copyFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const HERE = new URL('.', import.meta.url).pathname;
const OR = `${HERE}oracle/`;
const SCRATCH = process.env.PHASE0_SCRATCH || '/tmp';

const run = (args) => {
  try { return execFileSync('node', [`${HERE}parity.mjs`, ...args], { encoding: 'utf8' }) + '\n[exit 0]'; }
  catch (e) { return (e.stdout ?? '') + (e.stderr ?? '') + `\n[exit ${e.status}]`; }
};
const backup = (f) => { copyFileSync(OR + f, `${SCRATCH}/phase0-bak-${f}`); };
const restore = (f) => { copyFileSync(`${SCRATCH}/phase0-bak-${f}`, OR + f); };

const cases = [];

// 1. one byte of a frozen output
{
  const f = 'banxico.fixtures.out.jsonl';
  backup(f);
  const b = Buffer.from(readFileSync(OR + f));
  // RECORD FORMAT v1: records open with the version field, and this needle names the frozen bytes.
  const needle = Buffer.from('"34-2010/3.6/p4/signatory":{"v":1,"result":"member"}');
  const i = b.indexOf(needle);
  const off = i + '"34-2010/3.6/p4/signatory":{"v":1,"result":"memb'.length;
  const was = String.fromCharCode(b[off]);
  b[off] = 'f'.charCodeAt(0);
  writeFileSync(OR + f, b);
  cases.push({
    title: 'ONE BYTE OF A FROZEN OUTPUT',
    what: `\`${f}\` byte ${off}, \`${was}\` to \`f\`, so the frozen result token for 34-2010/3.6/p4/signatory reads \`membfr\`. Exactly one byte differs; \`cmp -l\` reports one line.`,
    out: run(['--candidate=hand', '--domain=banxico']),
  });
  restore(f);
}

// 2. a candidate diverging only deep in the population, where the frozen side is a digest
cases.push({
  title: 'A CANDIDATE DIVERGING BEYOND THE VERBATIM SET',
  what: 'The hand-written evaluator with one result token rewritten: `overdue` to `exceeded` on 34-2010/3.6/p4/deadline. `overdue` first occurs at sampled record 526, which is past the 250 records frozen verbatim, so the oracle side is a digest. The harness re-runs the evaluator for that record and CHECKS the re-run against the frozen digest before printing it as the oracle value.',
  out: run(['--candidate=mutant', '--domain=banxico', '--mutate=34-2010/3.6/p4/deadline:overdue:exceeded']),
});

// 3. one hex character of a frozen digest
{
  const f = 'banxico.sample.digests.txt';
  backup(f);
  const b = Buffer.from(readFileSync(OR + f));
  const off = 5000 * 16;
  const was = String.fromCharCode(b[off]);
  b[off] = was === '0' ? '1'.charCodeAt(0) : '0'.charCodeAt(0);
  writeFileSync(OR + f, b);
  cases.push({
    title: 'ONE HEX CHARACTER OF A FROZEN DIGEST',
    what: `\`${f}\`, record 5000's digest, first character \`${was}\` flipped. The candidate is the hand-written evaluator, so nothing about it has changed; what has changed is the oracle.`,
    out: run(['--candidate=hand', '--domain=banxico']),
  });
  restore(f);
}

// 4. the population moved
{
  const f = 'MANIFEST.json';
  backup(f);
  const m = JSON.parse(readFileSync(OR + f, 'utf8'));
  const h = m.domains.banxico.populations['sample-wide'].input_stream_sha256;
  m.domains.banxico.populations['sample-wide'].input_stream_sha256 = (h[0] === '0' ? '1' : '0') + h.slice(1);
  writeFileSync(OR + f, JSON.stringify(m, null, 1));
  cases.push({
    title: 'THE POPULATION MOVED',
    what: 'The frozen digest of the sampled INPUT stream is altered, standing for a change to `_corpus/space.mjs`. The candidate and the oracle were then not asked the same question, and the harness must say so rather than report either a pass or a failure.',
    out: run(['--candidate=hand', '--domain=banxico']),
  });
  restore(f);
}

const clean = run(['--candidate=hand']);
const restored = clean.includes('PARITY: IDENTICAL.');

const md = `# The parity harness, shown failing

Generated by \`show-parity-fails.mjs\`. Do not edit by hand: rerun it.

Instruments carry the shape of their subject, and this estate has five instances of one doing so. A
harness that has only ever passed is not yet a check. Each case below perturbs exactly one thing and
records what the harness printed, verbatim.

${cases.map((c, i) => `---

## ${i + 1}. ${c.title}

**What was perturbed.** ${c.what}

\`\`\`
${c.out.trim()}
\`\`\`
`).join('\n')}
---

## The oracle afterwards

Every perturbation is reverted by this script. Re-run over all three domains, candidate \`hand\`:

\`\`\`
${clean.trim().split('\n').slice(-4).join('\n')}
\`\`\`

**Restored: ${restored ? 'YES' : 'NO, AND THAT IS A FAILURE OF THIS SCRIPT'}.**
`;
writeFileSync(`${HERE}HARNESS-SHOWN-FAILING.md`, md);
console.log(`written: ${HERE}HARNESS-SHOWN-FAILING.md`);
console.log(`oracle restored: ${restored}`);
process.exit(restored ? 0 : 1);
